CREATE OR REPLACE FUNCTION public.icash_assign_seller_opener_v6(p_account uuid, p_thread uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare existing public.icash_seller_opener_assignments;plan jsonb;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_text_threads where id=p_thread and account_id=p_account and party='seller' for update;
 if not found then return null;end if;
 select * into existing from public.icash_seller_opener_assignments where thread_id=p_thread and account_id=p_account;
 if found then return jsonb_build_object('variant',existing.variant,'body',existing.body,'context',existing.learning_context);end if;
 if not public.icash_seller_cash_questions_enabled() then return public.icash_assign_seller_opener_v5(p_account,p_thread);end if;
 plan:=public.icash_seller_cash_question_plan(p_account,p_thread);if plan is null then return null;end if;
 insert into public.icash_seller_opener_assignments(thread_id,account_id,variant,body,learning_context)
 values(p_thread,p_account,plan->>'variant',plan->>'body','cash-question-v6');return plan;
end $function$

CREATE OR REPLACE FUNCTION icash_learning_private.record_policy_application()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d icash_learning_policy_private.decisions;s icash_learning_policy_private.settings;a bigint;src text;src_key text;expected jsonb;
begin
 if tg_op='UPDATE' then
  if old.learning_decision_id is not null and row(new.learning_decision_id,new.learning_policy_version,new.learning_selection_mode,new.variant) is distinct from row(old.learning_decision_id,old.learning_policy_version,old.learning_selection_mode,old.variant) then raise exception 'Learning allocation is immutable';end if;
  if old.learning_decision_id is null and new.learning_decision_id is not null then raise exception 'Historical allocation cannot be relabelled';end if;
  return new;
 end if;
 if new.learning_decision_id is null then return new;end if;
 select * into d from icash_learning_policy_private.decisions where id=new.learning_decision_id;
 if not found or new.learning_policy_version is distinct from d.policy_version or new.learning_selection_mode is null or new.learning_selection_mode not in ('control','explore','shared')
  or d.created_at not between now()-interval '6 hours' and now() or not (new.variant=any(d.choices))
  or (new.learning_selection_mode='shared' and (d.decision->>'status' is distinct from 'shared' or d.decision->>'winner' is distinct from new.variant)) then raise exception 'Allocation decision mismatch';end if;
 if d.stats is distinct from public.icash_shared_learning_stats(d.domain,d.context,d.market) then raise exception 'Allocation evidence changed';end if;
 select * into s from icash_learning_policy_private.settings where id=1;
 if tg_table_name='icash_learning_assignments' then
  if row(new.domain,new.context,new.market) is distinct from row(d.domain,d.context,d.market) then raise exception 'Allocation cohort mismatch';end if;
  expected:=icash_learning_private.expected_shared_allocation(new.account_id,new.domain,new.subject,new.context,d.decision,coalesce(s.enabled,false));
  if expected is null or expected->>'variant' is distinct from new.variant or expected->>'mode' is distinct from new.learning_selection_mode then raise exception 'Deterministic allocation mismatch';end if;
  src:='shared_assignment';src_key:=md5(jsonb_build_array(new.account_id,new.domain,new.subject)::text);
 else
  if d.domain<>'seller_sms' or d.context is distinct from new.learning_context or d.market<>'*' then raise exception 'Allocation cohort mismatch';end if;
  expected:=public.icash_seller_sms_learning_plan(new.account_id,new.thread_id);
  if expected is null or expected->>'variant' is distinct from new.variant or expected->>'mode' is distinct from new.learning_selection_mode or expected->>'body' is distinct from new.body or expected->'stats' is distinct from d.stats or expected->'decision' is distinct from d.decision then raise exception 'Seller SMS allocation mismatch';end if;
  src:='seller_sms';src_key:=new.thread_id::text;
 end if;
 select * into s from icash_learning_policy_private.settings where id=1;
 -- Disabled policy decisions may still be observed; activation is separate proof.
 if not coalesce(s.enabled,false) or s.release_sha is null or s.activated_at is null or s.activated_at>now() or s.policy_version<>d.policy_version then return new;end if;
 if d.created_at<s.evidence_after then raise exception 'Stale release decision';end if;
 if src='seller_sms' and not exists(select 1 from icash_learning_policy_private.sms_settings where id=1 and enabled) then return new;end if;
 if not exists(select 1 from icash_learning_private.policy_releases where release_sha=s.release_sha and completed_at<=s.activated_at and registered_at<=now()) then raise exception 'Verified policy release required';end if;
 insert into icash_learning_private.policy_applications(decision_id,source,source_key,release_sha,domain,context,market,policy_version,variant,mode)
 values(d.id,src,src_key,s.release_sha,d.domain,d.context,d.market,d.policy_version,new.variant,new.learning_selection_mode) returning id into a;
 update icash_learning_private.policy_cohorts set latest_application_id=a where (domain,context,market,policy_version)=(d.domain,d.context,d.market,d.policy_version);
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_record_learning_decision(p_domain text, p_context text, p_market text, p_stats jsonb, p_choices text[], p_require_contracts boolean DEFAULT false)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result bigint;computed jsonb;fingerprint text;canonical jsonb;epoch timestamptz;release text;
begin
 if length(p_domain) not between 1 and 100 or length(p_context) not between 1 and 100 or length(p_market) not between 1 and 100
  or p_domain is null or p_context is null or p_market is null or p_stats is null or octet_length(p_stats::text)>262144 then raise exception 'Invalid learning evidence';end if;
 if p_require_contracts is distinct from false or not coalesce(
  (p_domain='seller_calls' and p_context in ('reviewed','limited') and p_market='*' and p_choices=array['cash_interest','flexible_timing'])
  or (p_domain='buyer_search' and p_context='order-v1' and p_market ~ '^[0-9]{5}$' and p_choices=array['recent_corporate','corporate_owners'])
  or (p_domain='seller_sms' and p_context='identity-v5' and p_market='*' and cardinality(p_choices)>0
   and p_choices<@array['identity_cash_v5','identity_as_is_v5','identity_timing_v5']),false) then raise exception 'Unreviewed learning evidence scope';end if;
 select evidence_after,release_sha into epoch,release from icash_learning_policy_private.settings where id=1;
 canonical:=public.icash_shared_learning_stats(p_domain,p_context,p_market);
 if p_stats is distinct from canonical then raise exception 'Learning evidence does not match canonical observations';end if;
 computed:=public.icash_learning_decision_v2(canonical,p_choices,p_require_contracts);
 if computed->>'reason'='invalid_choices' then raise exception 'Invalid learning choices';end if;
 fingerprint:=md5(jsonb_build_object('stats',p_stats,'choices',p_choices,'requireContracts',p_require_contracts,'decision',computed,'snapshotHour',date_trunc('hour',now()),'evidenceEpoch',epoch,'releaseSha',release)::text);
 insert into icash_learning_policy_private.decisions(domain,context,market,policy_version,decision,stats,choices,require_contracts,evidence_hash)
 values(p_domain,p_context,p_market,'evidence-v2',computed,p_stats,p_choices,p_require_contracts,fingerprint)
 on conflict(domain,context,market,policy_version,evidence_hash) do nothing returning id into result;
 if result is null then select id into result from icash_learning_policy_private.decisions where domain=p_domain and context=p_context and market=p_market and policy_version='evidence-v2' and evidence_hash=fingerprint;end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_cash_question_plan(p_account uuid, p_thread uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare address text;principal text;choices text[];chosen text;unit text;bucket bigint;eligible boolean;
begin
 if not public.icash_seller_cash_questions_enabled() then return null;end if;
 select public.icash_conversation_street(d.terms->>'address'),trim(coalesce(nullif(trim(i.company_name),''),i.principal)),coalesce(nullif(j.snapshot->>'propertyId',''),t.id::text)
 into address,principal,unit from public.icash_text_threads t
 join public.icash_deal_files d on d.id=t.deal_id and d.account_id=t.account_id
 join public.icash_screening_jobs j on j.id=d.screening_id and j.account_id=d.account_id
 join public.icash_customer_identities i on i.account_id=t.account_id
 where t.id=p_thread and t.account_id=p_account and t.party='seller';
 if nullif(principal,'') is null then return null;end if;
 eligible:=public.icash_seller_sms_learning_eligible(p_account,p_thread);
 select array_agg(v.key order by v.key) into choices from public.icash_seller_opener_variants v
 where v.enabled and v.key in ('cash_sale_v6','all_cash_v6','cash_offer_v6')
 and v.body=replace(public.icash_seller_cash_question(v.key,'ADDRESS'),'ADDRESS','{address}')
 and public.icash_seller_cash_question(v.key,address) is not null;
 if coalesce(cardinality(choices),0)=0 then return null;end if;
 bucket:=('x'||substr(md5(p_account::text||unit||':cash-question-v6'),1,8))::bit(32)::bigint;
 chosen:=case when eligible then choices[1+bucket%cardinality(choices)] when 'cash_sale_v6'=any(choices) then 'cash_sale_v6' else choices[1] end;
 return jsonb_build_object('variant',chosen,'body',public.icash_seller_cash_question(chosen,address),'context','cash-question-v6');
end $function$
